"""TASK B4 — OPTIONAL gated self-training from MMCQS (NOT run by default).

For a sample of MMCQS queries, get predictions from three heads (rule layer,
calibrated classifier, Groq zero-shot). Keep only queries where all three AGREE,
confidence >= 0.8, and no red flag is involved. Write 100 kept rows to
pseudo_review.csv (blank human_label) for manual review. Then retrain with the
kept rows ADDED TO TRAINING ONLY (never validation) and compare grouped-CV
macro-F1 and emergency_112 recall. The pseudo-labelled data is kept only if
macro-F1 does not drop AND emergency recall does not drop.

Results are written to ml/external/selftrain_results.json (never to
docs/MODEL_COMPARISON.md, which is generated by ml/compare_models.py).
"""
from __future__ import annotations

import csv
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent.parent))

RAW_DIR = Path(__file__).resolve().parent / "raw"
REVIEW_CSV = Path(__file__).resolve().parent / "pseudo_review.csv"
RESULTS_JSON = Path(__file__).resolve().parent / "selftrain_results.json"

SAMPLE_N = 600
REVIEW_N = 100
AGREE_CONF = 0.8


def _load_queries(n: int) -> list[str]:
    path = RAW_DIR / "mmcqs_hf.jsonl"
    queries = []
    if path.exists():
        with open(path, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if line:
                    queries.append(json.loads(line).get("Codemixed_Question", ""))
    return [q for q in queries if q and q.strip()][:n]


def _rule_pred(q: str) -> tuple[str, bool]:
    from app.core.intake import rule_based_extract
    from app.core.triage_model import rule_based_predict
    slots = rule_based_extract(q)
    ct, _, _, conf = rule_based_predict(slots, q)
    red_flag = ct == "emergency_112"
    return ct, red_flag


def _classifier_pred(q: str) -> tuple[str, float, bool]:
    from app.core.triage_model import load_artifacts, predict_triage
    load_artifacts()
    from app.core.intake import rule_based_extract
    slots = rule_based_extract(q)
    ct, _, _, conf, _, _ = predict_triage(slots, q)
    return ct, conf, (ct == "emergency_112")


def _groq_pred(q: str) -> str | None:
    from pydantic import BaseModel
    from app.core.llm import groq_json
    from app.config import settings

    class CareTypeOut(BaseModel):
        care_type: str

    system = (
        "Classify into exactly one official care_type: paramedic_home_visit, home_nursing, "
        "lab_test_home, teleconsultation, emergency_112. Return valid JSON."
    )
    res = groq_json(system=system, user=f"Request: {q!r}", schema=CareTypeOut,
                    model=settings.GROQ_FAST_MODEL or settings.GROQ_MODEL)
    if res:
        ct = getattr(res, "care_type", None) or (res.get("care_type") if isinstance(res, dict) else None)
        return ct if ct in ("paramedic_home_visit", "home_nursing", "lab_test_home",
                            "teleconsultation", "emergency_112") else None
    return None


def agreement_pass(queries: list[str]) -> list[dict]:
    from app.core.llm import is_groq_available
    kept = []
    for q in queries:
        rule_ct, rule_rf = _rule_pred(q)
        cls_ct, cls_conf, cls_rf = _classifier_pred(q)
        if rule_rf or cls_rf:
            continue
        if cls_conf < AGREE_CONF:
            continue
        if rule_ct != cls_ct:
            continue
        # Groq head is optional; if unavailable, keep rule==classifier agreement.
        if is_groq_available():
            g = _groq_pred(q)
            if g is None or g != cls_ct:
                continue
        kept.append({"query": q, "care_type": cls_ct, "confidence": cls_conf, "source": "pseudo_mmcqs"})
    return kept


def main() -> None:
    queries = _load_queries(SAMPLE_N)
    if not queries:
        print("No MMCQS data available.")
        return
    kept = agreement_pass(queries)
    review = kept[:REVIEW_N]
    with open(REVIEW_CSV, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["user_input", "care_type", "confidence", "source", "human_label"])
        for r in review:
            writer.writerow([r["query"], r["care_type"], r["confidence"], r["source"], ""])
    print(f"Kept {len(kept)} agreed rows; wrote {len(review)} to {REVIEW_CSV} for human review.")

    results = {
        "note": "Gated self-training. Retrain + grouped-CV comparison is run separately "
                "(see ml/compare_models.py); keep pseudo-labels only if macro-F1 and "
                "emergency_112 recall do not drop.",
        "sampled": len(queries),
        "kept_agreement": len(kept),
        "review_written": len(review),
    }
    RESULTS_JSON.write_text(json.dumps(results, indent=2), encoding="utf-8")
    print(f"Wrote {RESULTS_JSON}")


if __name__ == "__main__":
    main()
